//! What Settings › Licenses lists: the libraries Fast is built from and the assets it
//! bundles. The library list is generated by `scripts/third_party.py` from
//! `cargo metadata`, so the app needs no network or toolchain to show it.

use std::sync::OnceLock;

use serde::Deserialize;

#[derive(Clone, Debug, Deserialize, PartialEq, Eq)]
pub struct Library {
    pub name: String,
    pub version: String,
    /// An SPDX expression, as the crate declares it.
    pub license: String,
    pub repository: Option<String>,
}

impl Library {
    /// Whether a search matches the name or the licence, ignoring case.
    pub fn matches(&self, query: &str) -> bool {
        let query = query.trim().to_lowercase();
        query.is_empty()
            || self.name.to_lowercase().contains(&query)
            || self.license.to_lowercase().contains(&query)
    }
}

/// Every crate in `Cargo.lock` outside the workspace, by name.
pub fn libraries() -> &'static [Library] {
    static LIBRARIES: OnceLock<Vec<Library>> = OnceLock::new();
    LIBRARIES.get_or_init(|| {
        serde_json::from_str(include_str!("../third_party.json")).unwrap_or_else(|err| {
            log::error!("the bundled library list is unreadable: {err}");
            Vec::new()
        })
    })
}

