/// How many libraries use each licence, commonest first. `A/B` is the old way of
/// writing `A OR B`, so the two are counted together.
pub fn license_counts(libraries: &[Library]) -> Vec<(String, usize)> {
    let mut counts: Vec<(String, usize)> = Vec::new();
    for library in libraries {
        let license = normalise(&library.license);
        match counts.iter_mut().find(|(known, _)| *known == license) {
            Some((_, count)) => *count += 1,
            None => counts.push((license, 1)),
        }
    }
    counts.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    counts
}

/// "MIT/Apache-2.0" and "Apache-2.0 OR MIT" both become "Apache-2.0 OR MIT".
fn normalise(license: &str) -> String {
    let spelled = license.replace(" / ", " OR ").replace('/', " OR ");
    // Simple alternatives are put in a stable order; anything with brackets or AND
    // is kept as written.
    if spelled.contains('(') || spelled.contains(" AND ") || spelled.contains(" WITH ") {
        return spelled;
    }
    let mut parts: Vec<&str> = spelled.split(" OR ").map(str::trim).collect();
    parts.sort_unstable();
    parts.join(" OR ")
}

#[cfg(test)]
mod tests {
    use super::*;

    /// `(name, version)` of every package from a registry or git in a lock file.
    fn locked(lock: &str) -> Vec<(String, String)> {
        let mut out = Vec::new();
        for block in lock.split("[[package]]").skip(1) {
            let field = |key: &str| {
                block.lines().find_map(|line| {
                    let value = line.strip_prefix(&format!("{key} = "))?;
                    Some(value.trim_matches('"').to_owned())
                })
            };
            // Packages without a source are the workspace's own crates.
            if field("source").is_none() {
                continue;
            }
            if let (Some(name), Some(version)) = (field("name"), field("version")) {
                out.push((name, version));
            }
        }
        out.sort();
        out
    }

    #[test]
    fn the_list_matches_cargo_lock() {
        let lock = include_str!("../../../Cargo.lock");
        let mut listed: Vec<(String, String)> = libraries()
            .iter()
            .map(|library| (library.name.clone(), library.version.clone()))
            .collect();
        listed.sort();
        assert_eq!(
            listed,
            locked(lock),
            "the library list is stale: run python3 scripts/third_party.py"
        );
        assert!(
            libraries()
                .iter()
                .all(|library| !library.license.is_empty())
        );
    }

    #[test]
    fn licences_are_counted_whatever_their_spelling() {
        let library = |license: &str| Library {
            name: "x".to_owned(),
            version: "1".to_owned(),
            license: license.to_owned(),
            repository: None,
        };
        let counts = license_counts(&[
            library("MIT/Apache-2.0"),
            library("MIT OR Apache-2.0"),
            library("Apache-2.0 OR MIT"),
            library("MIT"),
            library("(MIT OR Apache-2.0) AND Unicode-3.0"),
        ]);
        assert_eq!(counts[0], ("Apache-2.0 OR MIT".to_owned(), 3));
        assert_eq!(counts.len(), 3);
        assert!(library("Zlib").matches("zlib"));
        assert!(library("MIT").matches(""));
        assert!(!library("MIT").matches("gpl"));
    }
}
